const gptResp = $input.first().json;
const ctx = $('Start').first().json;

let parsed;
try {
  parsed = JSON.parse(gptResp.choices[0].message.content);
} catch(e) {
  parsed = { parsed_datetime: null, is_flexible: true, preference_text: 'next available slot' };
}

// If no specific time given, default to next 7 days window
const now = new Date();
const startTime = parsed.parsed_datetime
  ? new Date(parsed.parsed_datetime).toISOString()
  : now.toISOString();
const endTime = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString();

return [{
  json: {
    session_id: ctx.session_id,
    lead_id: ctx.lead_id,
    visitor_name: ctx.visitor_name || '',
    visitor_email: ctx.visitor_email || '',
    start_time: startTime,
    end_time: endTime,
    preference_text: parsed.preference_text || 'flexible'
  }
}];

// Find the consultation event type (first active one)
const eventTypes = $input.first().json;
const ctx = $('Prepare Calendly Request').first().json;

const consultationEvent = eventTypes.collection?.find(e =>
  e.name.toLowerCase().includes('consultation') ||
  e.name.toLowerCase().includes('strategy') ||
  e.name.toLowerCase().includes('free')
) || eventTypes.collection?.[0];

if (!consultationEvent) {
  throw new Error('No active Calendly event types found. Please create a consultation event in Calendly.');
}

return [{
  json: {
    ...ctx,
    event_type_uri: consultationEvent.uri,
    event_type_slug: consultationEvent.slug,
    event_name: consultationEvent.name,
    duration_mins: consultationEvent.duration
  }
}];

const availability = $input.first().json;
const ctx = $('Extract Event Type URI').first().json;

// Get top 3 available slots
const slots = availability.collection?.slice(0, 3) || [];

if (slots.length === 0) {
  return [{
    json: {
      ...ctx,
      slots_text: "No available slots found in the requested timeframe. Please visit " + $env.CALENDLY_BOOKING_URL + " to book directly.",
      has_slots: false,
      booking_url: process.env.CALENDLY_BOOKING_URL || 'https://calendly.com/synergistic-ai'
    }
  }];
}

// Format slots for human-readable display
const formatSlot = (slotStr) => {
  const d = new Date(slotStr);
  return d.toLocaleString('en-US', {
    weekday: 'long', month: 'short', day: 'numeric',
    hour: 'numeric', minute: '2-digit', timeZone: 'America/New_York'
  }) + ' ET';
};

const slotsText = slots.map((s, i) => `${i+1}. ${formatSlot(s.start_time)}`).join('\n');
const slotISOs = slots.map(s => s.start_time);

return [{
  json: {
    ...ctx,
    slots_text: slotsText,
    slot_isos: slotISOs,
    has_slots: true,
    booking_url: process.env.CALENDLY_BOOKING_URL || 'https://calendly.com/synergistic-ai'
  }
}];
